import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {
  // ============ REFS ============
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const detectionIntervalRef = useRef(null);
  const detectionTimeoutRef = useRef(null);
  const progressIntervalRef = useRef(null);

  // ============ STATE ============
  const [cameraActive, setCameraActive] = useState(false);
  const [detecting, setDetecting] = useState(false);
  const [detectionProgress, setDetectionProgress] = useState(0);
  const [capturedPhoto, setCapturedPhoto] = useState(null);
  const [matchResult, setMatchResult] = useState(null);
  const [error, setError] = useState(null);
  const [cameraPermission, setCameraPermission] = useState(null);
  const [videoReady, setVideoReady] = useState(false);

  // ============ VÉRIFIER PERMISSIONS ============
  useEffect(() => {
    const checkPermission = async () => {
      try {
        const result = await navigator.permissions.query({ name: 'camera' });
        setCameraPermission(result.state);
        result.onchange = () => setCameraPermission(result.state);
      } catch (e) { console.warn("Permissions API non supportée"); }
    };
    checkPermission();
  }, []);

  // ============ DÉMARRAGE CAMÉRA (FIX ÉCRAN NOIR) ============
  const startCamera = async () => {
    try {
      setError(null);
      console.log('🎥 Initialisation caméra...');

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: 'user' },
        audio: false
      });

      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;

        // Configuration forcée pour navigateurs PC
        videoRef.current.muted = true;
        videoRef.current.setAttribute('muted', '');
        videoRef.current.setAttribute('playsinline', '');

        // Déclencheur dès que les données arrivent
        videoRef.current.onloadeddata = async () => {
          try {
            await videoRef.current.play();
            setVideoReady(true);
            setCameraActive(true);
            console.log('✅ Flux vidéo actif');
          } catch (err) {
            console.error("Play bloqué:", err);
            // Backup : essai après 500ms
            setTimeout(() => videoRef.current?.play(), 500);
          }
        };
      }
    } catch (err) {
      setError("Impossible d'accéder à la caméra : " + err.message);
      addNotification?.("Erreur caméra", "error");
    }
  };

  // ============ ARRÊT CAMÉRA ============
  const stopCamera = () => {
    if (detectionIntervalRef.current) clearInterval(detectionIntervalRef.current);
    if (detectionTimeoutRef.current) clearTimeout(detectionTimeoutRef.current);
    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    setCameraActive(false);
    setVideoReady(false);
    setDetecting(false);
  };

  useEffect(() => { return () => stopCamera(); }, []);

  // ============ LOGIQUE DÉTECTION 10s ============
  const startDetection = () => {
    if (!videoReady) return;

    setDetecting(true);
    setDetectionProgress(0);
    setMatchResult(null);
    setError(null);

    let bestMatch = null;
    const startTime = Date.now();
    const DURATION = 10000;

    // Scan toutes les 600ms
    detectionIntervalRef.current = setInterval(async () => {
      if (!videoRef.current) return;

      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      canvas.getContext('2d').drawImage(videoRef.current, 0, 0);
      const imgBase64 = canvas.toDataURL('image/jpeg', 0.8);

      try {
        const res = await attendanceAPI.recognize(imgBase64);
        const data = res?.data;
        if (data?.success && data?.confidence > 0.35) {
          if (!bestMatch || data.confidence > bestMatch.confidence) {
            bestMatch = { ...data, photo: imgBase64 };
          }
        }
      } catch (e) { console.warn("Erreur scan"); }
    }, 600);

    // Barre de progression
    progressIntervalRef.current = setInterval(() => {
      const elapsed = Date.now() - startTime;
      setDetectionProgress(Math.min(100, (elapsed / DURATION) * 100));
    }, 100);

    // Fin du chrono
    detectionTimeoutRef.current = setTimeout(() => {
      clearInterval(detectionIntervalRef.current);
      clearInterval(progressIntervalRef.current);
      setDetecting(false);

      if (bestMatch) {
        setCapturedPhoto(bestMatch.photo);
        setMatchResult({
          name: bestMatch.student,
          email: bestMatch.email || 'N/A',
          confidence: (bestMatch.confidence * 100).toFixed(1),
          timestamp: new Date().toLocaleTimeString()
        });
        addNotification?.(`✅ Détecté : ${bestMatch.student}`, 'success');
      } else {
        setError("Aucun visage reconnu en 10 secondes.");
      }
    }, DURATION);
  };

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1 style={styles.title}>👤 Pointage Facial</h1>
        <p style={styles.subtitle}>Alignez votre visage pour valider votre présence</p>
      </header>

      {/* Caméra Section */}
      <div style={styles.videoSection}>
        <div style={styles.videoContainer}>
          {/* L'élément vidéo est toujours présent pour éviter les bugs de référence */}
          <video 
            ref={videoRef} 
            style={{ ...styles.video, opacity: videoReady ? 1 : 0 }} 
            muted 
            playsInline
          />

          {!cameraActive && (
            <div style={styles.overlay}>
              <button onClick={startCamera} style={{ ...styles.btn, background: COLORS.success }}>
                Allumer la Caméra
              </button>
            </div>
          )}

          {cameraActive && (
            <div style={{ ...styles.statusBadge, background: detecting ? COLORS.primary : COLORS.success }}>
              {detecting ? '🔄 SCAN EN COURS...' : '✅ PRÊT'}
            </div>
          )}
        </div>

        {detecting && (
          <div style={styles.progressBar}>
            <div style={{ ...styles.progressFill, width: `${detectionProgress}%` }} />
          </div>
        )}
      </div>

      {/* Actions */}
      <div style={styles.actions}>
        <button 
          onClick={startDetection} 
          disabled={!cameraActive || detecting} 
          style={{ ...styles.btn, background: (!cameraActive || detecting) ? '#94A3B8' : COLORS.warning }}
        >
          🔍 Lancer la Détection (10s)
        </button>
        <button onClick={stopCamera} style={{ ...styles.btn, background: COLORS.danger }}>
          🛑 Éteindre
        </button>
      </div>

      {error && <div style={styles.errorBox}>{error}</div>}

      {/* Résultats */}
      {matchResult && (
        <div style={styles.resultSection}>
          <h2 style={styles.resultTitle}>Étudiant Reconnu !</h2>
          <div style={styles.imagesGrid}>
            <div style={styles.imageColumn}>
              <p style={styles.imageTitle}>Profil</p>
              <div style={styles.imagePlaceholder}>👤</div>
            </div>
            <div style={styles.imageColumn}>
              <p style={styles.imageTitle}>Capture</p>
              <div style={styles.imagePlaceholder}>
                <img src={capturedPhoto} alt="Capture" style={styles.image} />
              </div>
            </div>
          </div>
          <div style={styles.infoBox}>
            <div style={styles.infoRow}><strong>Nom:</strong> <span>{matchResult.name}</span></div>
            <div style={styles.infoRow}><strong>Score:</strong> <span style={{color: COLORS.success}}>{matchResult.confidence}%</span></div>
            <div style={styles.infoRow}><strong>Heure:</strong> <span>{matchResult.timestamp}</span></div>
          </div>
          <button onClick={() => setMatchResult(null)} style={{ ...styles.btn, background: COLORS.primary, width: '100%', marginTop: 15 }}>
            Recommencer
          </button>
        </div>
      )}
    </div>
  );
};

